// Generated from Hedge Magic, Revised Edition, Chapter Seven (The Runes): each rune's guidelines and
// the book's sample rune scripts. A guideline of level 0 is General: any level, its magnitude the bonus.

export interface RuneGuideline { rune: string; level: number; general: boolean; text: string }
export interface RuneScriptDef { name: string; runes: string[]; level: number; method: 'I' | 'II' | 'III'; text: string; line: number }

export const RUNE_TEXTS: Record<string, { text: string; line: number }> = {
  Ansuz: { text: "This rune has many meanings, including \"mouth\" as in the source of speech and also the beginning of a river. It originated as \"god,\" as it is associated with the Norse gods who are called the Aesir (\"AYS-eyr\"), and particularly symbolizes Odin, the father of the gods, who first discovered the power of the runes. When used to describe a target, Ansuz most commonly refers to images, specifically sounds. For the purposes of Penetration, this application is an Imaginem effect. Ansuz can also affect the mind through speech, an aspect of Mentem, and in rare circumstances it can target the human mouth directly as a Corpus effect. It is also occasionally associated with Vim, to target intelligent supernatural beings that have the power of speech.", line: 6515 },
  Berkanan: { text: "The birch is a tree of fertility; its branches are bare and do not produce flowers or seeds, but it sprouts many shoots and leaves. In Norse legend, Odin marked the runes on nine birch twigs and then struck an adder with them, so that it was killed and divided into nine parts. The Berkanan rune is associated with healing, and also with youth. When used as a target it is usually Herbam, though it can also affect children (Corpus), and young animals (Animal).", line: 6549 },
  Dagaz: { text: "Dagaz means \"day,\" as in the length of time it takes the sun to travel from horizon to horizon. Thus, the rune is associated with the concept of time. It also represents the sun, light, and life during long, cold winters. Things grow over time, and so Dagaz is also associated with the growth of animals, plants, and people. As a target, Dagaz would be considered part of either Imaginem or Ignem, specifically affecting the light of day and moving images associated with time passing, but it is rarely used in this way.", line: 6595 },
  Ehwaz: { text: "This rune stands for the horse — a beast noted for its stamina, speed, and strength. It represents superior mobility in combat, as well as the close relationship between horse and rider. When used as a target, it is associated with Animal, specifically when targeting horses or other animals used in battle.", line: 6627 },
  Fehu: { text: "Fehu is the rune of wealth, represented by good fortune and prosperity. In contrast to Othila, which is associated with things such as land and heirlooms, Fehu is typically thought of as common wealth — things like cattle and other animals, silver pennies or surplus grain — but not tools, clothing, or weapons. In the Norwegian and Icelandic rune poems, wealth is more cynically viewed as a \"source of discord among kinsmen\" perhaps in reference to the brutal nature of Viking raids. When used as a target, Fehu is usually associated with either Animal or Terram, depending upon the type of wealth affected by the rune. It can be used to affect animals in general, but only those that are domesticated and thus considered property.", line: 6659 },
  Gebo: { text: "Accepting a gift places the recipient under certain obligations in Norse society, which usually involves the need to return the favor with another gift of similar value, so that neither party is in the other's debt. Thus, while this rune does represent openhanded charity and generosity, it also represents an arrangement or promise that binds the recipient. Gebo is not associated with any particular Form, but with any physical object given as a gift. It can also be used to target someone in the vitkir's debt, through that sense of obligation created by the vitkir's generosity. In this case, it might be considered a Mentem effect.", line: 6693 },
  Hagalaz: { text: "Hagalaz represents the cruelest side of nature, from sudden storms to debilitating illness. It means hail, both in terms of weather and a hail of missiles. It is associated with great destruction and harm, and always brings pain and suffering to its target. In the rune poems it is called \"the whitest of grain, whirled from the vault of the heavens and tossed about by wind before finally turning to water.\" It is a powerful force that is difficult to control. When used as a target, Hagalaz is almost always part of Auram or specific aspects of Aquam (cold, rain, and hail). It can also affect other sorts of missile weapons, including Terram (stones) and Herbam (arrows).", line: 6725 },
  Isa: { text: "Isa means ice, and it symbolizes the hidden dangers ice represents, such as slipping or breaking. It embodies coldness, and also cold emotions. As a target, Isa is associated with literal ice (Aquam), or Ignem when affecting temperature, or Mentem when affecting a person's cold and implacable feelings.", line: 6757 },
  Jera: { text: "Jera signifies the harvest, and while this implies autumn it can also mean the bounty of nature all year round. The harvest is also the end result of hard work for an entire year, and so the rune also has connotations of prosperity and plenty. As a target, Jera is almost always associated with the form of Herbam, though it can also influence an Animal harvest, and can target people's health and general well being through Corpus.", line: 6787 },
  Kauno: { text: "In the Anglo-Saxon Rune Poem, Kauno is described as a torch visible from afar, while other rune poems refer to it as an abscess or boil. As a pale, bright flame it could also refer to a fever, which \"burns where princes sit within.\" Thus, the rune symbolizes heat, the color and light of flames, and burning pain. Asa target, Kauno affects any kind of fire, as well as heat and temperature. It is almost always associated with Ignem when evaluating Penetration, though effects that cause sores and pain are usually Corpus or Animal.", line: 6815 },
  Laguz: { text: "This rune represents water, especially of the ocean. There is great wealth and power in the ocean, and many hidden dangers that cannot be seen from the surface. As a target it is almost always associated with Aquam, though it can also affect things that are only found underwater, such as water-breathing animals and sea plants.", line: 6869 },
  Mannaz: { text: "Mannaz means mankind, and suggests unity and cooperation among all people. When used as a target it affects either the mind or the body, but most often the body, and thus is usually linked to Corpus rather than Mentem. It is used most frequently to affect a person as the target of another rune.", line: 6903 },
  Naudiz: { text: "Naudiz is a very negative rune, meaning hardship, trouble, and adversity, often scratched onto a fingernail to indicate great need. It may be used to target things that are desperate, dying, or despairing, and so is usually associated with Mentem or Corpus.", line: 6933 },
  Ingwaz: { text: "Ingwaz is associated with peace, family, and a safe, secure home. As a target, it may affect a building, dwelling, or structure, and so is often tied to Herbam and Terram. It can also affect all those who live in a particular house, making it possible to target them by carving runes on the outside, or to target members of the caster's family or household. This is usually a Corpus effect.", line: 6964 },
  Othila: { text: "The Othila rune means property, but specific material goods as opposed to Fehu, which represents general wealth. These are things that can be passed'on from generation to generation, such as lands or possessions, and thus the rune is most often used as a target tied to Terram.", line: 6992 },
  Perth: { text: "Perth is a mysterious and strange rune, with many different interpretations. Perhaps the strongest association is with fate and chance, though it is also tied to pleasure and relaxation, such as found at a gaming table or dining hall. Thus, it typically represents a container that holds secrets, such as a dice cup or drinking horn. In the Anglo-Saxon Rune Poem it represents a piece on a gaming board, a pawn. Often Perth is used to affect the supernatural realms, particularly Magic. It is thus tied most strongly to Vim. It can target vis, and it can also target other spells and supernatural effects. It does not affect supernatural beings and creatures with Might (these are Ansuz if they are intelligent, or Uruz if they are not), though it can affect their powers.", line: 7018 },
  Raido: { text: "This rune is generally held to mean \"riding,\" as in the activity of going forth on horseback or on a cart. The word raido may be related to the Old Norse word reid, which means either chariot or thunder, and thus it may invoke Thor, the Norse god of thunder, who rode in a great chariot. It symbolizes a journey, and all forms of travel. It also conveys the idea of preparation for war or severe weather, and is thus associated with principles of planning, thought, and strategy. As a target, Raido targets a cart, ship, or wheel, as well as the tack and harnesses of animals that pull a cart or chariot. The animals themselves are usually associated with either Ehwaz if they are horses, or Fehu for other domesticated animals.", line: 7052 },
  Sowilo: { text: "Sowilo is associated with light and the sun, and is described as a boon to sailors and a blessing for travelers. It also has overtones of good succeeding against evil, much as light triumphs over dark. As a target Sowilo affects light, and is thus a part of the Form of Ignem. It can also target the Divine and beings that have Divine Might as a subset of Vim.", line: 7088 },
  Tiwaz: { text: "Tyr is the Norse god of truth and battle, giver of victory and protector of the other gods. He is loyal to his fellows and known for sacrificing his hand to the Fenris wolf so that it could be bound. His rune is associated with men who fight for the good of their companions, and who seek truth. As a target, it is primarily associated with Mentem and justice, in that it affects a person's thoughts and deeper motivations.", line: 7124 },
  Thurisaz: { text: "Thurisaz is interpreted many different ways, usually with a negative connotation. The Norse and Icelandic rune poems describe it as meaning \"giant\" or \"ogre,\" noting that such creatures especially like to harm women, while the Anglo-Saxon poem calls it \"thorn,\" being sharp and severe. The rune is also said to be used to evoke demons from the underworld. Its symbolism is generally evil and dangerous, and because of its association with trolls and ogres it is often used to cast spells that change the caster's shape. When used as a target, Thurisaz can affect supernatural creatures as a kind of Vim magic, these most commonly being infernal beings. It can also target thorny bushes and brambles as part of Herbam, or anything wooden that pierces or cuts.", line: 7156 },
  Uruz: { text: "This rune represents the aurochs, a large and powerful breed of cattle that roams the wilderness of Scandinavia. Julius Caesar described them as slightly smaller than the elephant and the same color and shape as a bull. They are extraordinarily strong, fast, and ferocious. Successfully hunting an aurochs makes a boy into a man, and the best way to do this is with a pit trap. Proof of the adventure is the display of the massive beast's horns, which are often bound at the tips with silver for use as drinking cups. Uruz is thus a symbol of strength and stamina, as well as manhood and masculinity. There is also a parallel implied in its defense against the hunter and a man defending his home, and in the great achievement of the hunter in besting the powerful beast. When used as a target, Uruz affects the form of Animal, specifically wild or magical animals. Because of its connection to the wilderness, Uruz is also associated with rain and wild weather, occasionally translated as \"drizzle,\" and so may also be part of Auram.", line: 7194 },
  Wunjo: { text: "This rune means comfort, bliss, and joy. This may be a sort of intoxication, or simply the absence of suffering, and it also has connotations of glory and success in battle. Those who work together towards a common goal also fall under Wunjo's influence. Wunjo is associated with Mentem, targeting the emotions of people and intelligent beings only.", line: 7234 },
  Ihwaz: { text: "Ihwaz refers to the yew tree, the wood of which is used to make longbows and which also has associations with death and witchcraft because of a traditional practice of planting it in graveyards. When used as a target, it may affect any sort of tree or bow and should be treated as an Herbam effect. The rune may also be used to target the spirits of the dead as a Mentem effect, or a gravesite as Terram.", line: 7264 },
  Algiz: { text: "This rune has many meanings, all of which mean some sort of protection. It is sometimes associated with the elk — which is said to sleep leaning against a tree so that it may more easily elude hunters — and with its antlers. The rune itself is often seen as a hand warding off a blow, and the word alu is often used in spells to mean \"protect me,\" perhaps referring to this rune. Another interpretation is as a kind of sedge-grass that grows in marshlands, which is so prickly that it cannot be grasped. In any case, this rune is most often used for the purposes of protecting a target. Algiz almost never refers to a target directly, though because of its symbolism it can be used to affect elk, a hand, or grass, and is thus associated with Animal, Corpus, or Herbam as appropriate.", line: 7304 },
};

